const item = $input.first()?.json || {};
const queryParams = $('Webhook').first()?.json?.query || {};
const action = (queryParams.action || 'add').toLowerCase();

const eventTitle = String(item.event || 'นัดหมาย').trim();
const location = String(item.location && item.location !== '-' ? item.location : '').trim();
const category = String(item.category || 'ทั่วไป').trim();
const eventId = String(item.eventId || item.id || 'natdee_event');

// 1. จัดการแยกส่วน วัน-เวลา จากฐานข้อมูล (เช่น '2026-09-20 13:00:00')
const rawDt = String(item.datetime || '').replace('T', ' ').trim();
const [datePart, timePart = '00:00'] = rawDt.split(' ');
const [year, month, day] = (datePart || '2026-01-01').split('-');
const [hour, min] = (timePart || '00:00').split(':');

// ฟอร์แมตเวลาตัวเลขล้วน (YYYYMMDDTHHmmss)
const startDt = `${year}${month}${day}T${hour}${min}00`;
const endHour = String((parseInt(hour, 10) + 1) % 24).padStart(2, '0');
const endDt = `${year}${month}${day}T${endHour}${min}00`;

const nowUtc = new Date().toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';

function escapeIcs(text) {
  return String(text || '')
    .replace(/\\/g, '\\\\')
    .replace(/;/g, '\\;')
    .replace(/,/g, '\\,')
    .replace(/\r?\n/g, '\\n');
}

const isCancel = action === 'cancel';
const method = isCancel ? 'CANCEL' : 'PUBLISH';
const status = isCancel ? 'CANCELLED' : 'CONFIRMED';
const sequence = isCancel ? '1' : '0';

const descriptionText = isCancel
  ? `❌ นัดหมายนี้ถูกยกเลิกแล้วผ่านระบบนัดดี (NatDee)\nหมวดหมู่: ${category}`
  : `🦉 บันทึกโดย นัดดี (NatDee)\nหมวดหมู่: ${category}\nสถานที่: ${location || '-'}\n\n📋 เช็กลิสต์การเตรียมตัว:\n- เผื่อเวลาเดินทางล่วงหน้า\n- ตรวจสอบสัมภาระและเอกสารที่ต้องใช้`;

// 2. ประกาศ VTIMEZONE เพื่อล็อกเขตเวลา Asia/Bangkok ให้ Google Calendar / iOS รับรู้ตรงกัน
const icsLines = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//NatDee Assistant//TH',
  'CALSCALE:GREGORIAN',
  `METHOD:${method}`,
  'BEGIN:VTIMEZONE',
  'TZID:Asia/Bangkok',
  'X-LIC-LOCATION:Asia/Bangkok',
  'BEGIN:STANDARD',
  'TZOFFSETFROM:+0700',
  'TZOFFSETTO:+0700',
  'TZNAME:+07',
  'DTSTART:19700101T000000',
  'END:STANDARD',
  'END:VTIMEZONE',
  'BEGIN:VEVENT',
  `UID:${eventId}@natdee.21missionboss.online`,
  `DTSTAMP:${nowUtc}`,
  `SEQUENCE:${sequence}`,
  `STATUS:${status}`,
  `DTSTART;TZID=Asia/Bangkok:${startDt}`,
  `DTEND;TZID=Asia/Bangkok:${endDt}`,
  `SUMMARY:${escapeIcs(eventTitle)}`,
  `DESCRIPTION:${escapeIcs(descriptionText)}`,
  `LOCATION:${escapeIcs(location)}`
];

if (!isCancel) {
  icsLines.push(
    'BEGIN:VALARM',
    'ACTION:DISPLAY',
    `DESCRIPTION:เตือนนัดหมาย: ${escapeIcs(eventTitle)} (อีก 15 นาที)`,
    'TRIGGER:-PT15M',
    'END:VALARM',
    'BEGIN:VALARM',
    'ACTION:DISPLAY',
    `DESCRIPTION:เตือนนัดหมาย: ${escapeIcs(eventTitle)} (อีก 1 ชั่วโมง)`,
    'TRIGGER:-PT1H',
    'END:VALARM'
  );
}

icsLines.push('END:VEVENT', 'END:VCALENDAR');

return [{
  json: {
    icsContent: icsLines.join('\r\n'),
    fileName: `appointment_${eventId}.ics`
  }
}];
